import{_ as e,o,c as d,a3 as a}from"./chunks/framework.FagJqzbK.js";const p=JSON.parse('{"title":"Model validation","description":"","frontmatter":{"order":30},"headers":[],"relativePath":"configuration/model-validation.md","filePath":"configuration/model-validation.md"}'),i={name:"configuration/model-validation.md"};function r(n,t,s,c,h,l){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="model-validation" tabindex="-1">Model validation <a class="header-anchor" href="#model-validation" aria-label="Permalink to &quot;Model validation&quot;">​</a></h1><p>Hindsight checks every temporal entity when the model is built, which is also when <code>dotnet ef migrations add</code> builds it. A configuration it cannot version correctly fails right there, with a message that names the entity and the fix, instead of producing a history table that silently misses changes.</p><table tabindex="0"><thead><tr><th>rejected</th><th>exception</th><th>why</th><th>what to do</th></tr></thead><tbody><tr><td>No primary key</td><td><code>InvalidOperationException</code></td><td>History rows are matched to their entity by key.</td><td>Give the entity a key.</td></tr><tr><td>Every primary-key property excluded with <code>Exclude(...)</code></td><td><code>InvalidOperationException</code></td><td>No column would be left to identify the entity&#39;s versions.</td><td>Keep at least one key property versioned.</td></tr><tr><td>Not mapped to a table</td><td><code>InvalidOperationException</code></td><td>There is no table to version.</td><td>Map the entity with <code>ToTable(...)</code>.</td></tr><tr><td>Owned reference (<code>OwnsOne</code>) or complex property</td><td><code>NotSupportedException</code></td><td>Their columns belong to another type, so history could not mirror them and would miss changes to them.</td><td>Make the entity standalone, or drop the owned or complex members.</td></tr><tr><td>Part of an inheritance hierarchy</td><td><code>NotSupportedException</code></td><td>Not supported in this version.</td><td>Map the entity on its own.</td></tr><tr><td>A column named like a history column: <code>history_id</code>, <code>operation</code>, <code>changed_by</code>, <code>changed_by_name</code>, <code>correlation_id</code>, <code>reason</code>, <code>extra</code>, or the entity&#39;s period columns</td><td><code>InvalidOperationException</code></td><td>The history table already has a column with that name.</td><td>Rename the column, exclude the property, or choose other period column names.</td></tr><tr><td>Period start and end with the same name</td><td><code>InvalidOperationException</code></td><td>They are two columns.</td><td>Choose two names.</td></tr><tr><td>A generated name over 63 bytes</td><td><code>InvalidOperationException</code></td><td>PostgreSQL silently truncates longer identifiers, so two entities could share a table, an index, or, silently, a trigger function.</td><td>Shorten the name with <code>UseHistoryTable(&quot;shorter_name&quot;)</code>, or rename the main table.</td></tr></tbody></table><p>The generated names are the history table, its two indexes, and in trigger mode the trigger function and the trigger; see <a href="/hindsight-efcore/nightly/migrations/generated-schema#generated-names">What a migration creates</a>. The limit is 63 bytes of UTF-8, not 63 characters. The longest ASCII main-table name that fits with the default history table name is 44 characters.</p><p>A history table name that collides with another table in the model is rejected too, by EF Core&#39;s own validation, since the history table is an ordinary entity type as far as EF Core is concerned.</p><p>Removing a primary-key property from an entity that is already temporal is also rejected; see <a href="/hindsight-efcore/nightly/migrations/schema-evolution#removing-a-primary-key-property">Evolving a temporal entity</a>.</p>',6)])])}const y=e(i,[["render",r]]);export{p as __pageData,y as default};
